f2b4","description":"Stipe","correct_answer":false},{"id":"01a21904-ad59-7de0-b08d-a35fa4669c95","description":"Gills","correct_answer":false},{"id":"01a21904-ad59-7a47-a81c-456fa4cd75c1","description":"Rhizome","correct_answer":false}]},{"id":"01a21904-ad59-78c3-8109-f3fb78d299d4","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the word for a young bat?","difficulty":3,"explanation":"A pup is the usual name for a young bat, and the term is also used for young seals and several other mammals.","alternatives":[{"id":"01a21904-ad59-7aa5-9051-b6b0a3694064","description":"A Pup","correct_answer":true},{"id":"01a21904-ad59-788f-b361-eca2aec80524","description":"A Colt","correct_answer":false},{"id":"01a21904-ad59-7f13-bea1-ad8fc4c24a72","description":"A Gosling","correct_answer":false},{"id":"01a21904-ad59-73ce-a96d-46e52d9c4da1","description":"A Cygnet","correct_answer":false}]},{"id":"01a21904-ad59-7296-ada2-1a85cdd37916","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"A young sea lion is known as what?","difficulty":3,"explanation":"Sea lion pups are born on land and nurse from their mothers.","alternatives":[{"id":"01a21904-ad59-7595-ae12-59acebf7f253","description":"A Pup","correct_answer":true},{"id":"01a21904-ad59-7d49-821c-569344d3b4fc","description":"A Foal","correct_answer":false},{"id":"01a21904-ad59-70cd-bb11-cb831f6386d7","description":"A Calf","correct_answer":false},{"id":"01a21904-ad59-71b9-b717-2c8f26317805","description":"A Piglet","correct_answer":false}]},{"id":"01a21904-ad59-7756-b05b-330e1ae25cf5","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which drug can be given to prevent blood clots?","difficulty":3,"explanation":"Aspirin reduces platelet clumping, which is why low-dose aspirin is sometimes used to lower the risk of certain blood clots.","alternatives":[{"id":"01a21904-ad59-7b8f-b2d7-06da6a74f3a8","description":"Aspirin","correct_answer":true},{"id":"01a21904-ad59-764b-ba92-d5c644703913","description":"Ibuprofen","correct_answer":false},{"id":"01a21904-ad59-72af-8d01-f8cda260291a","description":"Paracetamol","correct_answer":false},{"id":"01a21904-ad59-7748-a0f0-526c2f3f3907","description":"Morphine","correct_answer":false}]},{"id":"01a21904-ad59-7e02-bbf7-472074567b5a","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is Hepatology the study of?","difficulty":3,"explanation":"Hepatology focuses on the liver, which also helps filter waste products from the blood.","alternatives":[{"id":"01a21904-ad59-7962-a4de-856aef693370","description":"The liver","correct_answer":true},{"id":"01a21904-ad59-7cf2-962d-311970efc545","description":"Religion","correct_answer":false},{"id":"01a21904-ad59-7746-a272-c6f3b122083b","description":"The moon","correct_answer":false},{"id":"01a21904-ad59-716d-a68c-6ff312a6bd2d","description":"The number 7","correct_answer":false}]},{"id":"01a21904-ad59-71b2-904a-8d117f529d28","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is Oology the study of?","difficulty":3,"explanation":"Oology is a branch of ornithology focused on bird eggs, including their shells, shape, and markings.","alternatives":[{"id":"01a21904-ad59-7a13-89b5-2e3193228c1b","description":"eggs","correct_answer":true},{"id":"01a21904-ad59-7277-8bfe-8dc3436783e7","description":"organic particles, such as bacteria, fungal spores, very small insects and pollen","correct_answer":false},{"id":"01a21904-ad59-7827-9585-8cb7c8b8ff66","description":"genetic differences in relation to the environment","correct_answer":false},{"id":"01a21904-ad59-7002-ac07-0fe4fce89f44","description":"the structure of cells","correct_answer":false}]},{"id":"01a21904-ad59-7088-b373-b9c9ba3e126b","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which ancient Greek scholar calculated the circumference of the Earth around 240 BC?","difficulty":3,"explanation":"Eratosthenes compared the Sun\'s angle at Alexandria with its nearly overhead position at Syene, then used the distance between the cities to estimate Earth\'s circumference.","alternatives":[{"id":"01a21904-ad59-7d09-9bfe-1d010b5509bf","description":"Eratosthenes","correct_answer":true},{"id":"01a21904-ad59-71ab-abc0-41b7426aca5f","description":"Euclid","correct_answer":false},{"id":"01a21904-ad59-74b4-afaa-54f553f8fac3","description":"Ptolemy","correct_answer":false},{"id":"01a21904-ad59-70f3-a3e4-e2322227fa4a","description":"Hipparchus","correct_answer":false}]},{"id":"01a21904-ad59-7ea8-be87-40e4348acd01","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which American physicist built the first working laser in 1960, using a ruby crystal?","difficulty":3,"explanation":"Theodore Maiman\'s ruby laser used a flash lamp to excite the crystal, producing brief pulses of red light.","alternatives":[{"id":"01a21904-ad59-73d5-8930-96fd58895ec0","description":"Theodore Maiman","correct_answer":true},{"id":"01a21904-ad59-7444-93c6-2cee9a102ee1","description":"Charles Townes","correct_answer":false},{"id":"01a21904-ad59-70da-a72e-f00cf3aa40c5","description":"Gordon Gould","correct_answer":false},{"id":"01a21904-ad59-7a05-a130-42a34c154bbc","description":"Arthur Schawlow","correct_answer":false}]},{"id":"01a21904-ad59-719a-b000-c1ee9fd09d2c","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Where can we find the tympanic membrane?","difficulty":3,"explanation":"The tympanic membrane vibrates in response to sound and passes those vibrations to the three small bones in the middle ear.","alternatives":[{"id":"01a21904-ad59-7173-bdef-c26a8c881197","description":"Ear","correct_answer":true},{"id":"01a21904-ad59-751c-a065-0137dc16e0dd","description":"Nose","correct_answer":false},{"id":"01a21904-ad59-7dc0-ba02-1c955c35d138","description":"Mouth","correct_answer":false},{"id":"01a21904-ad59-7661-8498-22e246d24a29","description":"Eye","correct_answer":false}]},{"id":"01a21904-ad59-749b-891c-7a9855d59bca","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the word for a group of sparrows?","difficulty":3,"explanation":"A host of sparrows is a traditional collective noun; host also has an older sense of a large multitude.","alternatives":[{"id":"01a21904-ad59-7b85-8bbe-5b299fdb07b3","description":"A host","correct_answer":true},{"id":"01a21904-ad59-7ebc-961a-22f3f6bd8f9a","description":"A run","correct_answer":false},{"id":"01a21904-ad59-7171-ac0d-5c2d042730fa","description":"A field","correct_answer":false},{"id":"01a21904-ad59-7394-a8bd-564a69ac9233","description":"A charm","correct_answer":false}]},{"id":"01a21904-ad59-731e-a18d-0ef6166c1d23","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is Kymatology the study of?","difficulty":3,"explanation":"Kymatology comes from the Greek kyma, meaning wave; the field also applies to motions in sound and other physical systems.","alternatives":[{"id":"01a21904-ad59-7049-b9b5-4c9c7c038543","description":"waves or wave motions","correct_answer":true},{"id":"01a21904-ad59-77dd-bb16-c9755b31cafb","description":"weather","correct_answer":false},{"id":"01a21904-ad59-722d-b243-284e7653bcff","description":"Tibet","correct_answer":false},{"id":"01a21904-ad59-7307-a8bd-69477d221fdf","description":"mental processes in living creatures","correct_answer":false}]},{"id":"01a21904-ad59-70d8-8a6c-ae25a427e5a6","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the name of Earth\'s rigid outer shell, made up of the crust and uppermost mantle?","difficulty":3,"explanation":"The lithosphere is Earth\'s rigid outer shell, about 100 km thick, split into tectonic plates.","alternatives":[{"id":"01a21904-ad59-7533-b914-a8e5f07b817f","description":"Lithosphere","correct_answer":true},{"id":"01a21904-ad59-75ca-9a82-19ea70f9d9a4","description":"Atmosphere","correct_answer":false},{"id":"01a21904-ad59-72f5-864c-9a0871a27fdf","description":"Hydrosphere","correct_answer":false},{"id":"01a21904-ad59-7156-93a8-cc1436206e66","description":"Biosphere","correct_answer":false}]},{"id":"01a21904-ad59-725c-8c67-5b2db678b1d4","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is Semiology the study of?","difficulty":3,"explanation":"Semiology studies how signs convey meaning in communication and culture; the term is often used interchangeably with semiotics.","alternatives":[{"id":"01a21904-ad59-77de-bf43-1a96cf9ba372","description":"signs","correct_answer":true},{"id":"01a21904-ad59-742c-bf8f-dad64a9f8360","description":"is concerned with earth materials that can be utilized for economic and\/or industrial purposes","correct_answer":false},{"id":"01a21904-ad59-7168-9be7-85a069cd54c3","description":"the practice of escaping from restraints or other traps","correct_answer":false},{"id":"01a21904-ad59-7676-a061-3e0d72e85eef","description":"a branch of logic focusing on part-whole relationships","correct_answer":false}]},{"id":"01a21904-ad59-7d75-a1b8-fde6a24ab4eb","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is enology the study of?","difficulty":3,"explanation":"Enology is also spelled oenology; the term comes from the Greek word oinos, meaning wine.","alternatives":[{"id":"01a21904-ad59-745d-ab1e-100c9ebde3c0","description":"Wine and winemaking","correct_answer":true},{"id":"01a21904-ad59-76b2-ac8b-c14a5396a684","description":"Whales, dolphins and porpoises","correct_answer":false},{"id":"01a21904-ad59-7300-bde4-3806c46fe708","description":"Gross and disgusting things","correct_answer":false},{"id":"01a21904-ad59-7515-8bc5-148efa44f391","description":"Tibet","correct_answer":false}]},{"id":"01a21904-ad59-71ba-8a04-0a2f27947135","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"In geometry, what is the opposite of an acute angle?","difficulty":3,"explanation":"An obtuse angle measures more than 90 degrees but less than 180 degrees; an acute angle is less than 90 degrees.","alternatives":[{"id":"01a21904-ad59-79b7-853a-150b8f50710b","description":"Obtuse","correct_answer":true},{"id":"01a21904-ad59-729c-8b7a-1d4c8ce00444","description":"Chronic","correct_answer":false},{"id":"01a21904-ad59-787a-866e-93c688bed941","description":"Vector","correct_answer":false},{"id":"01a21904-ad59-7c29-81dd-b6db25e2144b","description":"Integral","correct_answer":false}]},{"id":"01a21904-ad59-7733-a769-6326b0199113","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What would you call a baby hare?","difficulty":3,"explanation":"A leveret is born furred and with its eyes open, unlike a newborn rabbit, which is typically blind and hairless.","alternatives":[{"id":"01a21904-ad59-7487-a355-8d737859fa99","description":"A Leveret","correct_answer":true},{"id":"01a21904-ad59-7f4e-bc4e-7c0db5817c70","description":"A Codling","correct_answer":false},{"id":"01a21904-ad59-741a-81dd-a5de4c86a661","description":"A Fawn","correct_answer":false},{"id":"01a21904-ad59-7313-93e3-e9614daea020","description":"A Maggot","correct_answer":false}]},{"id":"01a21904-ad59-73bc-b310-067bc9574f2c","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What would you call a male bee?","difficulty":3,"explanation":"A drone is a male honeybee. Unlike worker bees, drones do not gather pollen or have stingers.","alternatives":[{"id":"01a21904-ad59-7250-8d93-17402c2d6c8f","description":"A Drone","correct_answer":true},{"id":"01a21904-ad59-7800-8765-1ec37c724ed0","description":"A Buck","correct_answer":false},{"id":"01a21904-ad59-7a8d-a547-7e91cff4fe3f","description":"A Jack","correct_answer":false},{"id":"01a21904-ad59-7f58-840c-be2adaf0ff0e","description":"A Boar","correct_answer":false}]},{"id":"01a21904-ad59-79d7-8eb8-0ca7e37f298f","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is codicology the study of?","difficulty":3,"explanation":"Codicology studies handwritten books as physical objects, including their materials, construction, and production; paleography focuses more on their handwriting.","alternatives":[{"id":"01a21904-ad59-7de9-902a-e6884799b80d","description":"The preparation of books and manuscripts","correct_answer":true},{"id":"01a21904-ad59-7597-a6b7-86b65d55e50a","description":"Water","correct_answer":false},{"id":"01a21904-ad59-7dea-9789-f0573dd71278","description":"The nature and origins of knowledge","correct_answer":false},{"id":"01a21904-ad59-7746-af88-ce18240a48bf","description":"Microorganisms","correct_answer":false}]},{"id":"01a21904-ad59-777d-b2ed-a9b1ca7bbd5c","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the chemical calcium carbonate often used for?","difficulty":3,"explanation":"Limestone and marble are rich in calcium carbonate and have long been used in construction.","alternatives":[{"id":"01a21904-ad59-79dc-a883-f647790bf9e4","description":"It is used as a building material.","correct_answer":true},{"id":"01a21904-ad59-7692-9288-1034e4562ff2","description":"It is used to preserve food.","correct_answer":false},{"id":"01a21904-ad59-722c-b086-f623bb409e28","description":"It is used to manufacture dry wall.","correct_answer":false},{"id":"01a21904-ad59-79d3-8900-b68714debbe8","description":"It is used in laundry detergent.","correct_answer":false}]},{"id":"01a21904-ad59-78dd-a70a-17725bd7cba2","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which bone is NOT part of the human skull?","difficulty":3,"explanation":"Carpal bones form the wrist; the occipital and temporal bones are parts of the cranium, while the maxilla forms the upper jaw.","alternatives":[{"id":"01a21904-ad59-763d-8787-3f7617879cb0","description":"Carpal","correct_answer":true},{"id":"01a21904-ad59-7053-9a17-5b454c1f53dd","description":"Occipital","correct_answer":false},{"id":"01a21904-ad59-7503-9c39-30b48136dee9","description":"Temporal","correct_answer":false},{"id":"01a21904-ad59-74b3-9028-a8ee0f4f1c63","description":"Maxilla","correct_answer":false}]},{"id":"01a21904-ad59-7be5-8b7c-cbbadddba202","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What element is lacking in a diet when goitre occurs?","difficulty":3,"explanation":"Iodine is needed to make thyroid hormones; a deficiency can cause the thyroid gland to enlarge, forming a goitre.","alternatives":[{"id":"01a21904-ad59-7e84-af25-8807a7eae508","description":"Iodine","correct_answer":true},{"id":"01a21904-ad59-7760-bd34-2bcbcf145f73","description":"Potassium","correct_answer":false},{"id":"01a21904-ad59-725d-8aed-8b3b469dd372","description":"Chlorine","correct_answer":false},{"id":"01a21904-ad59-7cee-9a1a-0101b58b333d","description":"Iron","correct_answer":false}]},{"id":"01a21904-ad59-7673-bb4c-f62448bed6d2","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What protein is resposible for carrying oxygen in our blood?","difficulty":3,"explanation":"Hemoglobin contains iron-bearing heme groups that bind oxygen reversibly, giving red blood cells their color.","alternatives":[{"id":"01a21904-ad59-76fb-9a7c-cc78ed2016b4","description":"Hemoglobin","correct_answer":true},{"id":"01a21904-ad59-7136-86b3-ade883b1151c","description":"Histone","correct_answer":false},{"id":"01a21904-ad59-75c2-9ef4-fb7227de142e","description":"Histidin","correct_answer":false},{"id":"01a21904-ad59-7d00-aa6d-6cee93f9c541","description":"GABA","correct_answer":false}]},{"id":"01a21904-ad59-7f2e-aa04-9db08465e67f","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is the word for a group of mallards?","difficulty":3,"explanation":"A sord is a traditional collective noun for mallards. Mallards are also the wild ancestors of most domestic duck breeds.","alternatives":[{"id":"01a21904-ad59-70c9-89a9-cbaca64176ee","description":"A sord","correct_answer":true},{"id":"01a21904-ad59-79bf-8502-e525ec9bcd2f","description":"A parliament","correct_answer":false},{"id":"01a21904-ad59-706c-8d1b-0eea002e0b8f","description":"A paddling","correct_answer":false},{"id":"01a21904-ad59-7a1e-9063-545e849c6be2","description":"A skulk","correct_answer":false}]},{"id":"01a21904-ad